    BridgeExecutionFrame self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case BridgeExecutionFrame_Data(
        deliverySequence: final deliverySequence,
        event: final event,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_u_64(deliverySequence, serializer);
        sse_encode_box_autoadd_bridge_execution_event(event, serializer);
      case BridgeExecutionFrame_ResyncRequired(
        identity: final identity,
        reason: final reason,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_box_autoadd_bridge_thread_feed_identity(
          identity,
          serializer,
        );
        sse_encode_bridge_resync_reason(reason, serializer);
      case BridgeExecutionFrame_Failure(
        identity: final identity,
        error: final error,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_box_autoadd_bridge_thread_feed_identity(
          identity,
          serializer,
        );
        sse_encode_box_autoadd_bridge_error(error, serializer);
      case BridgeExecutionFrame_Closed(
        identity: final identity,
        reason: final reason,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_box_autoadd_bridge_thread_feed_identity(
          identity,
          serializer,
        );
        sse_encode_bridge_feed_closed_reason(reason, serializer);
    }
  }

