  @protected
  void sse_encode_bridge_observed_brief(
    BridgeObservedBrief self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case BridgeObservedBrief_Uninitialized(
        revision: final revision,
        updatedAt: final updatedAt,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_u_64(revision, serializer);
        sse_encode_i_64(updatedAt, serializer);
      case BridgeObservedBrief_Loading(
        revision: final revision,
        startedAt: final startedAt,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_u_64(revision, serializer);
        sse_encode_i_64(startedAt, serializer);
      case BridgeObservedBrief_Ready(
        revision: final revision,
        updatedAt: final updatedAt,
        lastCheckedAt: final lastCheckedAt,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_u_64(revision, serializer);
        sse_encode_i_64(updatedAt, serializer);
        sse_encode_opt_box_autoadd_i_64(lastCheckedAt, serializer);
      case BridgeObservedBrief_Refreshing(
        revision: final revision,
        startedAt: final startedAt,
        lastCheckedAt: final lastCheckedAt,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_u_64(revision, serializer);
        sse_encode_i_64(startedAt, serializer);
        sse_encode_opt_box_autoadd_i_64(lastCheckedAt, serializer);
      case BridgeObservedBrief_Stale(
        revision: final revision,
        staleAt: final staleAt,
        lastCheckedAt: final lastCheckedAt,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_u_64(revision, serializer);
        sse_encode_i_64(staleAt, serializer);
        sse_encode_opt_box_autoadd_i_64(lastCheckedAt, serializer);
      case BridgeObservedBrief_Degraded(
        revision: final revision,
        failedAt: final failedAt,
        lastCheckedAt: final lastCheckedAt,
        retryable: final retryable,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_u_64(revision, serializer);
        sse_encode_i_64(failedAt, serializer);
        sse_encode_opt_box_autoadd_i_64(lastCheckedAt, serializer);
        sse_encode_bool(retryable, serializer);
      case BridgeObservedBrief_Failed(
        revision: final revision,
        failedAt: final failedAt,
        retryable: final retryable,
      ):
        sse_encode_i_32(6, serializer);
        sse_encode_u_64(revision, serializer);
        sse_encode_i_64(failedAt, serializer);
        sse_encode_bool(retryable, serializer);
      case BridgeObservedBrief_Stopped(
        revision: final revision,
        stoppedAt: final stoppedAt,
      ):
        sse_encode_i_32(7, serializer);
        sse_encode_u_64(revision, serializer);
        sse_encode_i_64(stoppedAt, serializer);
    }
  }

